  function pendingBaseItems() { return allItems().filter((it) => { const status = slug(it.status); const purchaseStatus = slug(it.compra.status); return !status.includes('cancelado') && (['solicitado','nao comprado'].includes(status) || !it.compra.fornecedorId || ['rascunho','aguardando compra'].includes(purchaseStatus)); }); }
  function pendingFilteredItems() { const f = pendingState.filters; return pendingBaseItems().filter((it) => { const ids = itemOsIds(it); const first = ids[0]; const hay = slug(`${it.descricao} ${it.codigo} ${it.status} ${supplier(it.compra.fornecedorId).nome} ${ids.map((id)=>`${os(id).numero} ${vehicle(id).placa} ${vehicle(id).marca} ${vehicle(id).modelo}`).join(' ')}`); if (f.q && !hay.includes(slug(f.q))) return false; if (f.os && !ids.some((id)=>slug(os(id).numero || id).includes(slug(f.os)))) return false; if (f.placa && !ids.some((id)=>slug(vehicle(id).placa).includes(slug(f.placa)))) return false; if (f.status && slug(it.status) !== slug(f.status)) return false; if (f.atrasado && !isLateItem(it)) return false; if (f.semFornecedor && it.compra.fornecedorId) return false; if (f.semOs && first) return false; return true; }); }
  function pendingFiltersMarkup() { const f = pendingState.filters; const statuses = [...new Set(pendingBaseItems().map((it)=>it.status))]; return `<form class="filters-panel form-grid ${pendingState.filtersOpen ? '' : 'is-collapsed'}" data-pending-filters><label class="form-field"><span>Busca</span><input class="input" name="q" value="${esc(f.q || '')}" placeholder="Item, código, OS, placa"></label><label class="form-field"><span>OS</span><input class="input" name="os" value="${esc(f.os || '')}"></label><label class="form-field"><span>Placa</span><input class="input" name="placa" value="${esc(f.placa || '')}"></label><label class="form-field"><span>Status</span><select class="select" name="status"><option value="">Todos</option>${statuses.map((s)=>`<option value="${esc(s)}" ${f.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="check-field"><input type="checkbox" name="atrasado" value="sim" ${f.atrasado ? 'checked' : ''}> Somente atrasados</label><label class="check-field"><input type="checkbox" name="semFornecedor" value="sim" ${f.semFornecedor ? 'checked' : ''}> Sem fornecedor</label><label class="check-field"><input type="checkbox" name="semOs" value="sim" ${f.semOs ? 'checked' : ''}> Sem OS vinculada</label><div class="form-actions"><button class="btn btn-primary" type="submit">Aplicar filtros</button><button class="btn btn-secondary" type="button" data-pending-clear>Limpar</button></div></form>`; }
  function pendingTable(items) { const rows = items.map((it) => { const ids = itemOsIds(it); const first = ids[0]; const etapa = byId(d().etapasProducao, os(first).etapaId).nome || '—'; const cond = (os(first).condicoes || []).map((id)=>byId(d().condicoesParalelas,id).nome).join(', ') || 'Sem condição'; return [`<input type="checkbox" data-pending-select value="${it.id}" aria-label="Selecionar ${esc(it.descricao)}" ${pendingState.selected.has(it.id) ? 'checked' : ''}>`, `<strong>${it.descricao}</strong><br><small class="muted">${it.codigo || 'Sem código'}</small>`, osLinks(ids), vehicle(first).placa || '—', `${vehicle(first).marca || ''} ${vehicle(first).modelo || ''}`.trim() || '—', etapa, cond, fmt(it.compra.dataCompra), isLateItem(it) ? '<span class="badge danger">Alta</span>' : '<span class="badge">Normal</span>', supplier(it.compra.fornecedorId).nome, fmt(it.previsao), badge(it.status)]; }); return rows.length ? c().table(['<input type="checkbox" data-pending-select-all aria-label="Selecionar todos">','Item','OS','Placa','Veículo','Etapa principal','Condição paralela','Solicitação','Urgência','Fornecedor','Previsão','Status'], rows) : c().emptyState('Nenhum item pendente', 'Ajuste os filtros ou volte para compras.'); }
