  function updatePendingSelection(root) { const selected = root.querySelectorAll('[data-pending-select]:checked').length; root.querySelector('[data-pending-selected]').textContent = `${selected} selecionado(s)`; root.querySelectorAll('[data-pending-bulk]').forEach((btn)=>{ btn.disabled = selected === 0; }); const all = root.querySelector('[data-pending-select-all]'); const boxes = [...root.querySelectorAll('[data-pending-select]')]; if (all) { all.checked = boxes.length > 0 && boxes.every((box)=>box.checked); all.indeterminate = boxes.some((box)=>box.checked) && !all.checked; } }
  function pendingBulkAction(action, root) { const selected = [...root.querySelectorAll('[data-pending-select]:checked')].map((box)=>box.value); if (!selected.length) return c().toast('Selecione ao menos um item.'); if (action === 'cancel') { selected.forEach((id)=>{ const it = allItems().find((item)=>item.id===id); if (it) { it.status = 'cancelado'; addHistory(it.compra, 'cancelamento', `Item ${it.descricao} cancelado pela lista de pendentes.`, { itemId:it.id }); recalc(it.compra); } }); pendingState.selected.clear(); c().toast(`${selected.length} item(ns) cancelado(s).`); return renderPendingResults(root); } c().toast(`${selected.length} item(ns) selecionado(s) para ${action === 'create' ? 'criar pedido de compra' : 'incluir em pedido de compra'}.`); }
  function bindPending(root) { root.addEventListener('click', (e) => { const btn = e.target.closest('button'); if (!btn || btn.disabled) return; if (btn.matches('[data-pending-toggle-filters]')) { pendingState.filtersOpen = !pendingState.filtersOpen; root.querySelector('[data-pending-filters]').classList.toggle('is-collapsed', !pendingState.filtersOpen); } if (btn.matches('[data-pending-clear]')) { pendingState.filters = {}; pendingState.selected.clear(); pendingState.filtersOpen = true; root.querySelector('[data-pending-filters]').reset(); renderPendingResults(root); } if (btn.matches('[data-pending-bulk]')) pendingBulkAction(btn.dataset.pendingBulk, root); }); root.addEventListener('submit', (e)=>{ if (!e.target.matches('[data-pending-filters]')) return; e.preventDefault(); pendingState.filters = Object.fromEntries([...new FormData(e.target).entries()]); pendingState.selected.clear(); renderPendingResults(root); }); root.addEventListener('change', (e)=>{ if (e.target.matches('[data-pending-select-all]')) root.querySelectorAll('[data-pending-select]').forEach((box)=>{ box.checked = e.target.checked; e.target.checked ? pendingState.selected.add(box.value) : pendingState.selected.delete(box.value); }); if (e.target.matches('[data-pending-select]')) e.target.checked ? pendingState.selected.add(e.target.value) : pendingState.selected.delete(e.target.value); updatePendingSelection(root); }); }
  function renderPending() { const root = document.querySelector('[data-page-content]'); const items = pendingFilteredItems(); root.innerHTML = `<section class="page-hero"><div><div class="breadcrumb">Início / Suprimentos / Itens pendentes</div><h2>Itens pendentes</h2><p>Itens sem pedido de compra efetivo, prontos para seleção e ação em massa.</p></div><div class="hero-actions"><a class="btn btn-secondary" href="compras.html">Voltar para Compras</a></div></section><section class="section pending-purchases-page"><article class="card pending-items-card"><div class="section-header"><div><h3>Itens sem pedido</h3><p class="muted"><span data-pending-count>${items.length} item(ns) sem pedido</span> · <span data-pending-selected>0 selecionado(s)</span></p></div><div class="hero-actions"><button class="btn btn-secondary" data-pending-toggle-filters>Filtros</button><button class="btn btn-primary" data-pending-bulk="create" disabled>Criar pedido de compra</button><button class="btn btn-secondary" data-pending-bulk="include" disabled>Incluir em pedido de compra</button><button class="btn btn-danger" data-pending-bulk="cancel" disabled>Cancelar item</button></div></div>${pendingFiltersMarkup()}<div data-pending-results>${pendingTable(items)}</div></article></section>`; bindPending(root); updatePendingSelection(root); window.MeloComponents.bindComponents(); }

  function blankCompra() {
    const next = `PED-${2060 + d().compras.length}`;
    return { id:'nova-compra', pedido:next, pedidoExterno:'', fornecedorId:null, dataCompra:today, responsavel:'', previsaoEntrega:'', formaPagamento:'', condicaoPagamento:'', observacoes:'', necessitaContaPagar:true, contaPagarId:null, status:'rascunho', statusRecebimento:'rascunho', statusFinanceiro:'lançamento pendente', itens:[], recebimentos:[], divergencias:[], devolucoes:[], documentos:[], historico:[], osIds:[], isBlank:true, valor:0 };
  }
  function renderDetail() {
    syncOsCosts();
    const params = new URLSearchParams(location.search); const compra = params.get('new') === '1' ? blankCompra() : d().compras.find((p) => p.id === params.get('id') || p.pedido === params.get('id'));
    const root = document.querySelector('[data-page-content]');
    if (!compra) { root.innerHTML = `<section class="page-hero"><div><div class="breadcrumb">Início / Compras / Detalhe</div><h2>Compra não encontrada</h2><p>Verifique o parâmetro informado.</p></div><a class="btn btn-secondary" href="compras.html">Voltar</a></section>`; return; }
    root.innerHTML = detailMarkup(compra); bindDetail(root, compra);
  }
  function purchaseFreightInfo(compra) { const value = Number(compra.valorFrete ?? compra.frete ?? compra.itens.reduce((s,it)=>s+Number(it.freteProporcional || 0),0)); const mode = compra.tipoFrete || compra.formaEntrega || compra.modalidadeFrete || (value > 0 ? 'Entrega' : 'Retirada'); return { mode, value }; }
  function purchaseHeaderInfo(compra) { const s = supplier(compra.fornecedorId); const freight = purchaseFreightInfo(compra); return `<div class="purchase-detail-head"><div><span>Fornecedor</span><b>${s.nome}</b><small>${s.telefone || 'Sem contato'}</small></div><div><span>Data do pedido</span><b>${fmt(compra.dataCompra)}</b></div><div><span>Previsão</span><b>${fmt(compra.previsaoEntrega)}</b></div><div><span>Forma</span><b>${compra.formaPagamento || '—'}</b></div><div><span>Condição</span><b>${compra.condicaoPagamento || '—'}</b></div><div><span>Responsável</span><b>${compra.responsavel || '—'}</b></div><div><span>Total</span><b>${money(compra.valor)}</b></div><div><span>Frete</span><b>${freight.mode || '—'}</b><small>${money(freight.value)}</small></div><div class="wide"><span>Observações</span><b>${compra.observacoes || '—'}</b></div></div>`; }
  function detailMarkup(compra) { return `<section class="page-hero purchase-detail-hero"><div><div class="breadcrumb">Início / Suprimentos / Compras / ${compra.isBlank ? 'Nova compra' : compra.pedido}</div><h2>${compra.isBlank ? 'Novo pedido de compra' : compra.pedido}</h2><p>${badge(compra.status)} ${badge(compra.statusRecebimento)} ${badge(compra.statusFinanceiro)} · ${compra.osIds.length} OS(s) ${isLateCompra(compra) ? '<span class="badge danger">Atrasada</span>' : ''}</p>${purchaseHeaderInfo(compra)}</div><div class="hero-actions"><button class="btn btn-danger" data-detail-action="cancel">Cancelar pedido</button><button class="btn btn-secondary" onclick="window.print()">Imprimir</button></div></section><section class="section detail-page" data-detail-root>${detailTabs()}<div data-detail-tab-content>${tabOverview(compra)}</div></section>${modals()}`; }
  function detailTabs() { return `<div class="tabs"><button class="tab active" data-detail-tab="overview">Visão geral</button><button class="tab" data-detail-tab="items">Itens</button><button class="tab" data-detail-tab="os">Ordens de Serviço</button><button class="tab" data-detail-tab="receipts">Recebimentos</button><button class="tab" data-detail-tab="finance">Financeiro</button><button class="tab" data-detail-tab="docs">Documentos</button><button class="tab" data-detail-tab="history">Histórico</button></div>`; }
  function detailKpis(compra) { const pend = compra.itens.filter((it)=>itemPending(it)>0); return `<div class="grid grid-4">${c().kpiCard({label:'Itens totais',value:compra.itens.length,note:'linhas do pedido'})}${c().kpiCard({label:'Itens recebidos',value:compra.itens.filter((it)=>itemPending(it)===0).length,note:'sem pendência'})}${c().kpiCard({label:'Itens pendentes',value:pend.length,note:'inclui parciais'})}${c().kpiCard({label:'Valor total do pedido',value:money(compra.valor),note:'total da compra'})}</div>`; }
  function alerts(compra) { const arr = [isLateCompra(compra)&&'Compra atrasada', compra.statusRecebimento?.includes('parcial')&&'Recebimento parcial', compra.divergencias?.length&&'Divergência de quantidade/custo', compra.itens.some((it)=>!it.alocacoes?.length || Math.abs((it.alocacoes||[]).reduce((s,a)=>s+a.valor,0)-it.custoTotal)>0.01)&&'Item sem rateio completo', compra.necessitaContaPagar&&!compra.contaPagarId&&!isCanceled(compra)&&'Esta compra ainda não possui uma conta a pagar.', !compra.documentos?.some((doc)=>doc.categoria==='nota fiscal')&&'Documento fiscal ausente' ].filter(Boolean); return arr.length ? `<div class="alert-list">${arr.map((a)=>`<div class="alert-inline">${a}</div>`).join('')}</div>` : '<div class="alert-inline success">Sem alertas críticos nesta compra.</div>'; }
  function payableOverview(compra) { const payable = d().contasPagar.find((p)=>p.id===compra.contaPagarId); return `<article class="card"><div class="section-header"><div><h3>Contas a pagar</h3><p class="muted">${payable ? `Conta ${payable.id} lançada para este pedido.` : 'Ainda não há conta a pagar lançada para este pedido.'}</p></div>${!payable && !isCanceled(compra) ? '<button class="btn btn-primary" data-detail-action="payable">Lançar conta a pagar</button>' : ''}</div><div class="definition-grid"><span>Situação</span><b>${payable ? 'Lançada' : 'Pendente de lançamento'}</b><span>Conta vinculada</span><b>${payable ? payable.id : '—'}</b><span>Valor do pedido</span><b>${money(compra.valor)}</b><span>Valor lançado</span><b>${money(payable?.valor || 0)}</b><span>Vencimento</span><b>${fmt(payable?.vencimento)}</b><span>Status financeiro</span><b>${compra.statusFinanceiro}</b></div></article>`; }
  function deliveryOverview(compra) { const delivered = compra.itens.filter((it)=>itemPending(it)===0); const pending = compra.itens.filter((it)=>itemPending(it)>0); const itemLine = (it, type) => `<li><strong>${it.descricao}</strong><span>${type === 'pending' ? `${itemPending(it)} pendente(s) de ${it.quantidade}` : `${it.quantidadeRecebida} entregue(s)`}</span>${badge(it.status)}</li>`; return `<article class="card"><div class="section-header"><div><h3>Entregas dos itens</h3><p class="muted">Resumo simples do que já chegou e do que ainda está pendente.</p></div></div><div class="purchase-delivery-grid"><div><h4>Entregues</h4><ul class="simple-item-list">${delivered.map((it)=>itemLine(it,'delivered')).join('') || '<li><span>Nenhum item entregue integralmente.</span></li>'}</ul></div><div><h4>Pendentes</h4><ul class="simple-item-list">${pending.map((it)=>itemLine(it,'pending')).join('') || '<li><span>Nenhum item pendente.</span></li>'}</ul></div></div></article>`; }
